APP_ROLE = "axar_app"
# table -> privileges of the app role (append-only where history must not change)
INVENTORY_TABLES = {
    "items": "SELECT, INSERT, UPDATE",
    "suppliers": "SELECT, INSERT, UPDATE",
    "warehouses": "SELECT, INSERT, UPDATE",
    "supplier_documents": "SELECT, INSERT, UPDATE",       # draft -> posted
    "supplier_document_lines": "SELECT, INSERT",
    "stock_balances": "SELECT, INSERT, UPDATE",           # locked running totals
    "stock_movements": "SELECT, INSERT",                  # append-only ledger
    "recipes": "SELECT, INSERT",                          # new version, never edited
    "recipe_lines": "SELECT, INSERT",
    "production_batches": "SELECT, INSERT",
}


def secure_inventory_tables() -> None:
    policy = "tenant_id = current_setting('app.tenant_id', true)"
    grants = []
    for table, privs in INVENTORY_TABLES.items():
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"CREATE POLICY tenant_isolation ON {table} USING ({policy}) WITH CHECK ({policy})")
        grants.append(f"GRANT {privs} ON {table} TO {APP_ROLE}")
    grants.append(f"GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO {APP_ROLE}")
    body = "; ".join(grants)
    op.execute(f"DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{APP_ROLE}') "
               f"THEN {body}; END IF; END $$")


